diff --git a/components/ai-tool/parameter-field-utils.ts b/components/ai-tool/parameter-field-utils.ts
new file mode 100644
index 0000000..2d38a4e
--- /dev/null
+++ b/components/ai-tool/parameter-field-utils.ts
@@ -0,0 +1,239 @@
+import type { AiToolParameterField } from '@/types/ai-tool';
+
+export type UiParameterField = AiToolParameterField & {
+  name?: string;
+  min?: number;
+  max?: number;
+  defaultValue?: string | number;
+  supportedOptions?: unknown[];
+  multiple?: boolean;
+};
+
+const asRecord = (value: unknown): Record<string, unknown> | undefined =>
+  value && typeof value === 'object'
+    ? (value as Record<string, unknown>)
+    : undefined;
+
+const toNumber = (value: unknown): number | undefined =>
+  typeof value === 'number' ? value : undefined;
+
+const toStringOrNumber = (value: unknown): string | number | undefined =>
+  typeof value === 'string' || typeof value === 'number' ? value : undefined;
+
+const toUnknownArray = (value: unknown): unknown[] | undefined =>
+  Array.isArray(value) ? value : undefined;
+
+const toBoolean = (value: unknown): boolean | undefined =>
+  typeof value === 'boolean' ? value : undefined;
+
+const normalizeType = (value: unknown): UiParameterField['type'] =>
+  value === 'image' ||
+  value === 'text' ||
+  value === 'video' ||
+  value === 'number' ||
+  value === 'select'
+    ? value
+    : 'text';
+
+const getParameterData = (field: UiParameterField): Record<string, unknown> =>
+  asRecord(field.parameterData) ?? {};
+
+type NormalizeOptions = {
+  executorType?: 'GEMINI' | 'COMFYUI' | 'CHATGPT' | null;
+  fallbackName?: string;
+};
+
+export const normalizeParameterField = (
+  field: UiParameterField,
+  options: NormalizeOptions = {}
+): UiParameterField => {
+  const parameterData = getParameterData(field);
+
+  const nameFromGemini =
+    typeof parameterData.GeminiParameterFieldName === 'string'
+      ? parameterData.GeminiParameterFieldName
+      : undefined;
+  const nameFromFieldName =
+    typeof parameterData.fieldName === 'string'
+      ? parameterData.fieldName
+      : undefined;
+  const nameFromLegacy =
+    typeof field.name === 'string' ? field.name : undefined;
+  const resolvedName =
+    nameFromGemini || nameFromFieldName || nameFromLegacy || options.fallbackName;
+
+  const min = toNumber(parameterData.min) ?? toNumber(field.min);
+  const max = toNumber(parameterData.max) ?? toNumber(field.max);
+  const defaultValue =
+    toStringOrNumber(parameterData.defaultValue) ??
+    toStringOrNumber(field.defaultValue);
+  const supportedOptions =
+    toUnknownArray(parameterData.supportedOptions) ??
+    toUnknownArray(field.supportedOptions);
+  const multiple = toBoolean(parameterData.multiple) ?? toBoolean(field.multiple);
+
+  return {
+    type: normalizeType(field.type),
+    require: Boolean(field.require),
+    ...(typeof field.title === 'string' ? { title: field.title } : {}),
+    ...(typeof field.description === 'string'
+      ? { description: field.description }
+      : {}),
+    parameterData: {
+      ...parameterData,
+      ...(options.executorType === 'GEMINI' && resolvedName
+        ? { GeminiParameterFieldName: resolvedName }
+        : {}),
+      ...(options.executorType !== 'GEMINI' && resolvedName
+        ? { fieldName: resolvedName }
+        : {}),
+      ...(min !== undefined ? { min } : {}),
+      ...(max !== undefined ? { max } : {}),
+      ...(defaultValue !== undefined ? { defaultValue } : {}),
+      ...(supportedOptions !== undefined ? { supportedOptions } : {}),
+      ...(multiple !== undefined ? { multiple } : {})
+    }
+  };
+};
+
+export const normalizeGeminiParameterFields = (
+  rawFields: unknown,
+  defaultFields: UiParameterField[] = []
+): UiParameterField[] => {
+  if (!Array.isArray(rawFields) || rawFields.length === 0) {
+    return defaultFields.map((field) =>
+      normalizeParameterField(field, { executorType: 'GEMINI' })
+    );
+  }
+
+  const fields = rawFields
+    .filter((item): item is UiParameterField => !!item && typeof item === 'object')
+    .map((field) => normalizeParameterField(field, { executorType: 'GEMINI' }));
+
+  return fields.length > 0
+    ? fields
+    : defaultFields.map((field) =>
+        normalizeParameterField(field, { executorType: 'GEMINI' })
+      );
+};
+
+export const normalizeComfyUIParameterFields = (
+  rawSchema: unknown
+): UiParameterField[] => {
+  if (Array.isArray(rawSchema)) {
+    return rawSchema
+      .filter((item): item is UiParameterField => !!item && typeof item === 'object')
+      .map((field) => normalizeParameterField(field, { executorType: 'COMFYUI' }));
+  }
+
+  const schema = asRecord(rawSchema);
+  if (!schema || schema.type !== 'object') {
+    return [];
+  }
+
+  const properties = asRecord(schema.properties);
+  if (!properties) {
+    return [];
+  }
+
+  const required = Array.isArray(schema.required)
+    ? schema.required.filter((item): item is string => typeof item === 'string')
+    : [];
+
+  const fields: UiParameterField[] = [];
+  for (const [key, value] of Object.entries(properties)) {
+    const prop = asRecord(value) ?? {};
+    const enumOptions = Array.isArray(prop.enum)
+      ? prop.enum.filter(
+          (item): item is string | number =>
+            typeof item === 'string' || typeof item === 'number'
+        )
+      : undefined;
+
+    const fieldType: UiParameterField['type'] =
+      enumOptions && enumOptions.length > 0
+        ? 'select'
+        : prop.format === 'data-url' && prop.type === 'string'
+        ? 'image'
+        : prop.type === 'string'
+        ? 'text'
+        : prop.type === 'number'
+        ? 'number'
+        : 'text';
+
+    const field: UiParameterField = {
+      type: fieldType,
+      require: required.includes(key),
+      title: (prop.title as string) || key,
+      description: (prop.description as string) || '',
+      parameterData: {
+        fieldName: key,
+        ...(typeof prop.minimum === 'number' ? { min: prop.minimum } : {}),
+        ...(typeof prop.maximum === 'number' ? { max: prop.maximum } : {}),
+        ...(typeof prop.default === 'string' || typeof prop.default === 'number'
+          ? { defaultValue: prop.default }
+          : {}),
+        ...(enumOptions && enumOptions.length > 0
+          ? { supportedOptions: enumOptions }
+          : {})
+      }
+    };
+
+    fields.push(normalizeParameterField(field, { executorType: 'COMFYUI' }));
+  }
+
+  return fields;
+};
+
+export const getFieldName = (field: UiParameterField): string => {
+  const parameterData = getParameterData(field);
+  const geminiFieldName = parameterData.GeminiParameterFieldName;
+  if (typeof geminiFieldName === 'string' && geminiFieldName) {
+    return geminiFieldName;
+  }
+
+  const fieldName = parameterData.fieldName;
+  if (typeof fieldName === 'string' && fieldName) {
+    return fieldName;
+  }
+
+  return 'unknown';
+};
+
+export const getFieldMin = (field: UiParameterField): number | undefined => {
+  const parameterData = getParameterData(field);
+  return typeof parameterData.min === 'number' ? parameterData.min : undefined;
+};
+
+export const getFieldMax = (field: UiParameterField): number | undefined => {
+  const parameterData = getParameterData(field);
+  return typeof parameterData.max === 'number' ? parameterData.max : undefined;
+};
+
+export const getFieldDefaultValue = (
+  field: UiParameterField
+): string | number | undefined => {
+  const parameterData = getParameterData(field);
+  if (
+    typeof parameterData.defaultValue === 'string' ||
+    typeof parameterData.defaultValue === 'number'
+  ) {
+    return parameterData.defaultValue;
+  }
+
+  return undefined;
+};
+
+export const getFieldSupportedOptions = (
+  field: UiParameterField
+): unknown[] | undefined => {
+  const parameterData = getParameterData(field);
+  if (Array.isArray(parameterData.supportedOptions)) {
+    return parameterData.supportedOptions;
+  }
+
+  return undefined;
+};
+
+export const isFieldName = (field: UiParameterField, name: string): boolean =>
+  getFieldName(field) === name;
